+            busy_slow->MaybeSendBytesFromBuffer();
+        }
+        // Now we are done sending we are ready to disconnect despite being below the timeout.
+        BOOST_CHECK( busy_slow->ShouldDisconnect(now + timeout - 1s, timeout, /*disconnect_all=*/false));
+    }
